function appointmentRows(limit=100){let items=appointments().slice(0,limit);return items.length?items.map(a=>{let p=pros.find(p=>p.id===a.pro);return `<div class="row"><div class="rowleft"><div class="daybox"><small>${esc(dayName(a.date).split(' ')[2]||'')}</small><b>${a.date.slice(8)}</b></div><div><h3>${esc(a.groupTitle||p.service)}</h3><p>${state.role==='profissional'?esc(a.studentName||'Aluno da demonstração')+' · ':''}${p.name} · ${dayName(a.date)} · ${a.time}</p><span class="pill">${esc(a.status)} · simulado</span></div></div>${a.status==='Confirmado'?(state.role==='profissional'?`<div class="flex">${btn('Concluir','complete-appointment','secondary small',`data-id="${a.id}"`)}${btn('Ausência','no-show','secondary small',`data-id="${a.id}"`)}</div>`:btn('Cancelar','cancel-appointment','secondary small',`data-id="${a.id}"`)):icon('check')}</div>`}).join(''):`<div class="empty">Você ainda não tem agendamentos.<br><a href="#profissionais" class="textbtn">Encontre um profissional →</a></div>`}

function validVideoUrl(value){
 const text=String(value||'').trim();if(!text)return '';if(text.length>2048)return null;
 try{const u=new URL(text);const h=u.hostname.toLowerCase();if(u.protocol!=='https:'||u.username||u.password||u.port||!u.pathname.toLowerCase().endsWith('.mp4')||h==='localhost'||h.endsWith('.localhost')||h.endsWith('.local')||h.includes(':')||/^\d+\.\d+\.\d+\.\d+$/.test(h)||!h.includes('.'))return null;return u.href}catch{return null}
}
function createContent(data){
 if(state.role!=='profissional')return false;
 const title=String(data.title||'').trim(),text=String(data.text||'').trim(),videoUrl=validVideoUrl(data.videoUrl);
 if(!title||title.length>100||!text||text.length>2000||videoUrl===null){toast('Revise título, texto e link HTTPS de vídeo MP4.');return false}
 const authorized=data.authorized===true;
 state.professionalContents.unshift({id:uid(),pro:'p1',title,text,videoUrl,authorized,visible:authorized,date:new Date().toLocaleString('pt-BR')});audit('Conteúdo criado',title,authorized?'Exibição autorizada nesta demonstração':'Rascunho sem autorização');save();return true;
}
