function hydrationReminderCard(){if(state.role!=='aluno')return '';const r=hydrationReminder,locked=['running','paused'].includes(r.phase);return `<section class="card section"><div class="sectionhead"><div><h2>Lembrete de hidratação</h2><p>Escolha seu intervalo pessoal. O lembrete funciona enquanto o app estiver aberto e pode atrasar em segundo plano.</p></div><strong id="hydration-clock">${ReminderCore.formatRemaining(r.remaining)}</strong></div><div class="flex" style="flex-wrap:wrap"><label>Intervalo (5 a 120 minutos)<input id="hydration-minutes" type="number" min="5" max="120" step="1" value="${r.minutes}" ${locked?'disabled':''}></label><label class="content-consent"><input id="hydration-sound" type="checkbox" ${hydrationSound?'checked':''}> Som opcional</label>${btn(r.phase==='paused'?'Retomar':r.phase==='due'?'Iniciar outro lembrete':'Iniciar','hydration-start','secondary',r.phase==='running'?'disabled':'')}${btn('Pausar','hydration-pause','secondary',r.phase!=='running'?'disabled':'')}${btn('Cancelar','hydration-stop','secondary')}</div><p id="hydration-state" role="status" style="margin-top:12px">${hydrationStatus()}</p><small>Sem recomendação de volume. Não envia notificações quando o app está fechado.</small></section>`}
function hydrationStatus(){return {idle:'Lembrete desligado.',running:'Lembrete em andamento.',paused:'Lembrete pausado.',due:'Seu lembrete chegou.'}[hydrationReminder.phase]}
function prepareHydrationSound(){if(!hydrationSound)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw new Error('Unavailable');if(!hydrationAudio)hydrationAudio=new Audio();Promise.resolve(hydrationAudio.resume()).catch(()=>{hydrationSound=false;toast('Som indisponível. O alerta continua visual.')})}catch{hydrationSound=false;toast('Som indisponível. O alerta continua visual.')}}
function playHydrationSound(){if(!hydrationSound||!hydrationAudio)return;try{const oscillator=hydrationAudio.createOscillator(),gain=hydrationAudio.createGain(),now=hydrationAudio.currentTime;oscillator.frequency.value=880;gain.gain.setValueAtTime(.08,now);gain.gain.exponentialRampToValueAtTime(.001,now+.4);oscillator.connect(gain);gain.connect(hydrationAudio.destination);oscillator.start(now);oscillator.stop(now+.4);oscillator.onended=()=>{oscillator.disconnect();gain.disconnect()}}catch{hydrationSound=false}}
function startHydrationReminder(){if(state.role!=='aluno'||hydrationReminder.phase==='running')return false;const minutes=ReminderCore.validateMinutes($('#hydration-minutes')?.value??hydrationReminder.minutes);if(minutes===null){toast('Escolha um intervalo inteiro de 5 a 120 minutos.');return false}if(hydrationReminder.phase!=='paused')hydrationReminder=ReminderCore.createReminder(minutes);hydrationReminder=ReminderCore.startReminder(hydrationReminder);prepareHydrationSound();clearInterval(hydrationTicker);hydrationTicker=setInterval(tickHydrationReminder,1000);render();return true}
function tickHydrationReminder(now=Date.now()){if(state.role!=='aluno'){stopHydrationReminder();return}const before=hydrationReminder.phase;hydrationReminder=ReminderCore.tickReminder(hydrationReminder,now);if($('#hydration-clock'))$('#hydration-clock').textContent=ReminderCore.formatRemaining(hydrationReminder.remaining);if(before==='running'&&hydrationReminder.phase==='due'){clearInterval(hydrationTicker);hydrationTicker=null;playHydrationSound();toast('Seu lembrete de hidratação chegou.');if(route==='inicio')render()}}
function stopHydrationReminder(){hydrationReminder=ReminderCore.stopReminder(hydrationReminder);clearInterval(hydrationTicker);hydrationTicker=null;if(hydrationAudio){try{Promise.resolve(hydrationAudio.close()).catch(()=>{})}catch{}hydrationAudio=null}}

function brandStory(kind){const student=kind==='aluno';return `<section class="brand-story" aria-label="${student?'Sua jornada de bem-estar':'Cuidado com continuidade'}"><figure><img src="/assets/brand/${student?'aluno-movimento':'profissional-forca'}.jpeg" alt="${student?'Imagem de campanha: mulher com roupa esportiva em ambiente externo':'Imagem de campanha: homem em ambiente de treinamento'}" width="1600" height="939" decoding="async"><figcaption>Imagem ilustrativa da marca 369 WELLNESS</figcaption></figure><div class="brand-story-copy"><span class="eyebrow">${student?'SEU TEMPO. SEU RITMO.':'PESSOAS DIFERENTES. UM OBJETIVO.'}</span><h2>${student?'Seu cuidado tem continuidade.':'Os profissionais certos. Do seu lado, por mais tempo.'}</h2><p>${student?'Seu treino, sua rotina e quem acompanha você. Todos conectados para evoluir, um dia de cada vez.':'Aproxime o cuidado da rotina de cada aluno. Organize encontros, acompanhe a evolução e fortaleça essa relação.'}</p><a class="btn lime" href="#${student?'treino':'agenda'}">${student?'Ver meu treino':'Organizar minha agenda'} ${icon('arrow')}</a></div></section>`}
function home(){if(state.role!=='aluno')return dashboard();return head(`Olá, ${esc(state.profile.name)} <span style="font-weight:400">☀</span>`,'Cada pequeno passo faz parte da sua evolução.',`<span class="pill">${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}</span>`)+brandStory('aluno')+`<div class="hero-grid"><professional-discovery></professional-discovery><section class="card water"><div class="sectionhead"><h3>Uma pausa para se cuidar</h3>${icon('drop')}</div><div><div class="value">${(waterCount()/1000).toLocaleString('pt-BR')} <small>litros registrados hoje</small></div><p>Registre sua água ao longo do dia.</p><div class="progress"><span style="width:${Math.min(waterCount()/2500*100,100)}%"></span></div></div><div class="flex">${btn('+ 250 ml','water','secondary')}${btn('Desfazer','water-undo','secondary small')}<span class="spacer"></span><small>Registro diário</small></div></section></div>${hydrationReminderCard()}<div class="grid cols4 section">${stat('Treinos concluídos',Object.keys(state.completed).length,'workout')}${stat('Sessões agendadas',appointments().filter(a=>a.status==='Confirmado').length,'calendar')}${stat('Dias com registro',Object.keys(state.water).filter(k=>state.water[k]>0).length,'drop')}${stat('Profissionais disponíveis',5,'users')}</div>${professionalFeed()}<section class="section"><div class="sectionhead"><div><h2>Encontre quem cuida de você</h2><p>Profissionais de diferentes áreas para acompanhar sua jornada.</p></div><a class="textbtn" href="#profissionais">Ver todos →</a></div><div class="grid cols3">${pros.slice(0,3).map(proCard).join('')}</div></section><div class="grid cols2 section"><section class="card"><div class="sectionhead"><h2>Seus próximos encontros</h2><a class="textbtn" href="#agenda">Ver agenda →</a></div>${appointmentRows(2)}</section><section class="card"><div class="sectionhead"><h2>Uma semana de movimento</h2><span class="pill">Seus registros</span></div><p class="muted">A sua consistência faz a diferença.</p><div class="chart">${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let k=d.toLocaleDateString('en-CA'),done=dayCompleted(k);return `<div class="barcol"><div class="bar ${done?'done':''}" style="height:${done?85:12}px" title="${d.toLocaleDateString('pt-BR')}: ${done?'concluído':'sem treino concluído'}"></div><small>${d.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}</small></div>`}).join('')}</div></section></div>`}
function professionals(){let list=pros.filter(p=>(!filter||p.area===filter)&&(p.name+' '+p.specialty+' '+p.area).toLowerCase().includes(query.toLowerCase()));return head('Cuidado que conecta','Encontre o acompanhamento certo para cada momento da sua vida.')+`<div class="toolbar"><input id="search-pro" placeholder="Buscar nome ou especialidade" aria-label="Buscar profissionais" value="${esc(query)}"><select id="filter-pro" aria-label="Especialidade"><option value="">Todas as especialidades</option>${pros.map(p=>`<option ${filter===p.area?'selected':''}>${p.area}</option>`).join('')}</select></div><div class="notice">Perfis e avaliações fictícios para explorar a experiência. Nenhuma consulta real será marcada.</div><div class="grid cols3" id="pro-results">${list.map(proCard).join('')||'<div class="empty">Nenhum profissional encontrado.</div>'}</div>`}
const exercises=[['Agachamento livre','3 séries · 12 repetições · 60 s de pausa'],['Remada com halteres','3 séries · 12 repetições · 60 s de pausa'],['Elevação de quadril','3 séries · 15 repetições · 60 s de pausa'],['Prancha adaptada','3 séries · 20 segundos · 40 s de pausa']];
function activePlan(){return state.trainingPlan||{id:'default',title:'Movimento e força',goal:'Corpo inteiro',exercises:exercises.map(([name,description])=>({name,description}))}}
function planKey(){let id=activePlan().id;return id==='default'?dateKey():dateKey()+'::'+id}
function currentChecks(){return [...new Set((state.checks[planKey()]||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<activePlan().exercises.length))]}
function dayCompleted(date){return Object.keys(state.completed).some(k=>(k===date||k.startsWith(date+'::'))&&state.completed[k])}
let planDraft=null;
function draftPlan(){if(!planDraft){let plan=activePlan();planDraft={title:plan.title,goal:plan.goal,exercises:plan.exercises.map(x=>({name:x.name,sets:x.sets||3,quantity:x.quantity||12,unit:x.unit||'repetições',rest:x.rest??60,media:x.media||''}))}}return planDraft}
function savePlanDraft(){
 if(state.role!=='profissional')return false;const draft=draftPlan(),title=String(draft.title||'').trim(),goal=String(draft.goal||'').trim();
 if(!title||title.length>100||!goal||goal.length>160||draft.exercises.length<1||draft.exercises.length>12){toast('Preencha título, objetivo e de 1 a 12 exercícios.');return false}
 const normalized=[];
 for(const x of draft.exercises){const name=String(x.name||'').trim(),sets=Number(x.sets),quantity=Number(x.quantity),rest=Number(x.rest);if(!name||name.length>100||!Number.isInteger(sets)||sets<1||sets>10||!Number.isInteger(quantity)||quantity<1||quantity>100||!Number.isInteger(rest)||rest<0||rest>600||!['repetições','segundos'].includes(x.unit)){toast('Revise os exercícios: séries de 1 a 10, quantidade de 1 a 100 e descanso de 0 a 600 segundos.');return false}const media=String(x.media||'').trim();if(media&&!ExerciseMedia.safeExerciseGif(media)){toast('Use uma URL HTTPS de arquivo GIF, sem credenciais ou endereço local.');return false}normalized.push({name,sets,quantity,rest,media,unit:x.unit,description:sets+' séries · '+quantity+' '+x.unit+' · '+rest+' s de pausa'})}
 state.trainingPlan={id:uid(),title,goal,exercises:normalized};addPlanDemoNotice(state.trainingPlan);audit('Ficha de treino salva',title,normalized.length+' exercícios demonstrativos');save();toast('Ficha salva. Veja o resultado no perfil Aluno → Meu treino.');return true
}
function planEditor(){const draft=draftPlan();return head('Montar ficha de treino','Prepare uma ficha para explorar o fluxo do aluno.')+`<div class="notice">Ficha demonstrativa compartilhada entre os perfis deste navegador. Não representa uma prescrição ou acompanhamento real.</div><form id="plan-form" class="card"><div class="grid cols2"><label>Título da ficha<input id="plan-title" maxlength="100" required value="${esc(draft.title)}"></label><label>Objetivo<input id="plan-goal" maxlength="160" required value="${esc(draft.goal)}"></label></div>${draft.exercises.map((x,i)=>`<fieldset class="card section" style="background:#f7f9f3"><legend>Exercício ${i+1}</legend><label>Nome<input data-plan-index="${i}" data-plan-field="name" maxlength="100" required value="${esc(x.name)}"></label><div class="grid cols4"><label>Séries<input data-plan-index="${i}" data-plan-field="sets" type="number" min="1" max="10" step="1" required value="${esc(x.sets)}"></label><label>Quantidade<input data-plan-index="${i}" data-plan-field="quantity" type="number" min="1" max="100" step="1" required value="${esc(x.quantity)}"></label><label>Unidade<select data-plan-index="${i}" data-plan-field="unit"><option ${x.unit==='repetições'?'selected':''}>repetições</option><option ${x.unit==='segundos'?'selected':''}>segundos</option></select></label><label>Descanso (s)<input data-plan-index="${i}" data-plan-field="rest" type="number" min="0" max="600" step="1" required value="${esc(x.rest)}"></label></div><label>Mídia opcional (URL HTTPS de GIF)<input data-plan-index="${i}" data-plan-field="media" maxlength="2048" value="${esc(x.media||'')}" placeholder="https://…/exercicio.gif"></label><small>Cadastre somente uma mídia revisada para este exercício. O aluno escolhe quando abri-la.</small>${btn('Remover exercício','remove-plan-exercise','secondary small',`type="button" data-index="${i}" ${draft.exercises.length===1?'disabled':''}`)}</fieldset>`).join('')}<div class="flex section">${btn('Adicionar exercício','add-plan-exercise','secondary',`type="button" ${draft.exercises.length>=12?'disabled':''}`)}<button class="btn lime" type="submit">Salvar ficha demonstrativa</button></div></form>`}
function workout(){if(state.role==='profissional')return planEditor();let plan=activePlan(),checks=currentChecks(),done=!!state.completed[planKey()];return head('Meu treino','Seu espaço para acompanhar exercícios e registrar a evolução.')+`<div class="notice">Treino ilustrativo para testar o app. A prescrição real deve ser definida pelo profissional que acompanha você.</div><div class="grid cols2"><section class="card"><div class="sectionhead"><div><span class="eyebrow">FICHA DEMONSTRATIVA</span><h2>${esc(plan.title)}</h2></div><span class="pill">${esc(plan.goal)}</span></div><p class="muted">Rafael Costa · Personal trainer</p><div class="progress"><span style="width:${checks.length/plan.exercises.length*100}%"></span></div><small>${checks.length} de ${plan.exercises.length} exercícios registrados</small>${plan.exercises.map(({name,description,media},i)=>`<label class="exercise ${checks.includes(i)?'done':''}"><span class="num">${String(i+1).padStart(2,'0')}</span><div class="spacer"><h3>${esc(name)}</h3><p>${esc(description)}</p></div><input type="checkbox" data-exercise="${i}" ${checks.includes(i)?'checked':''} ${done?'disabled':''} aria-label="Concluir ${esc(name)}"></label>${ExerciseMedia.safeExerciseGif(media)?btn('Abrir mídia do exercício','exercise-media','secondary small',`data-index="${i}"`):''}`).join('')}<div style="margin-top:20px">${btn(done?'Treino registrado ✓':'Concluir treino','finish-workout','full',checks.length<plan.exercises.length||done?'disabled':'')}</div></section><div class="grid"><section class="card water"><h3>Tempo de descanso</h3><div class="value" id="timer">01:00</div><p>Um intervalo entre as séries.</p><div class="flex">${btn('Iniciar 60 s','timer','secondary')}${btn('Reiniciar','timer-reset','secondary')}</div></section><section class="card"><h2>Seu objetivo</h2><p class="muted" style="margin:12px 0">${esc(state.profile.goal)}</p><a class="textbtn" href="#perfil">Ajustar meu objetivo →</a><div class="row"><span>Treinos concluídos</span><strong>${Object.keys(state.completed).length}</strong></div></section></div></div>`}
function availability(pro,date){return state.availability[pro+'_'+date]||{released:false,blocked:[],deposit:25,cancelHours:24}}
function calendarMonth(){
  const [year,month]=agendaDate.split('-').map(Number), first=new Date(year,month-1,1), days=new Date(year,month,0).getDate();
  const pad=v=>String(v).padStart(2,'0');
  return `<section class="card section"><div class="sectionhead"><h2>${first.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h2><div class="flex">${btn('←','previous-month','secondary small','aria-label="Mês anterior"')}${btn('→','next-month','secondary small','aria-label="Próximo mês"')}</div></div><div class="monthgrid">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(d=>`<small>${d}</small>`).join('')}${'<span></span>'.repeat(first.getDay())}${Array.from({length:days},(_,i)=>{let date=year+'-'+pad(month)+'-'+pad(i+1), av=availability('p1',date), count=state.appointments.filter(a=>a.pro==='p1'&&a.date===date&&a.status==='Confirmado').length;return `<button class="monthday ${date===agendaDate?'selected':''} ${av.released?'released':''}" data-action="choose-day" data-date="${date}" aria-label="${i+1}: ${av.released?'liberado':'oculto'}, ${count} agendamentos" aria-pressed="${date===agendaDate}"><b>${i+1}</b><small>${count?count+' sessão'+(count>1?'s':''):av.released?'Liberado':'Oculto'}</small></button>`}).join('')}</div></section>`
}
const times=Array.from({length:19},(_,i)=>`${String(i+5).padStart(2,'0')}:00`);
function classAt(pro,date,time){return state.groupClasses.find(g=>g.pro===pro&&g.date===date&&g.time===time&&g.status!=='Cancelada')}
function classBookings(id){return state.appointments.filter(a=>a.groupId===id&&a.status!=='Cancelado')}
function canEnroll(g){if(!g||g.status==='Cancelada'||state.role!=='aluno'||new Date(g.date+'T'+g.time)<=new Date())return false;const av=availability(g.pro,g.date);return av.released&&!av.blocked.includes(g.time)&&classBookings(g.id).length<g.capacity&&!state.appointments.some(a=>a.groupId===g.id&&a.studentId==='viewer'&&a.status!=='Cancelado')}
function createClass(data){
 if(state.role!=='profissional')return false;const title=String(data.title||'').trim(),date=String(data.date||''),time=String(data.time||''),capacity=Number(data.capacity),priceText=String(data.price||''),price=Number(priceText);
 if(!title||title.length>100||!/^\d{4}-\d{2}-\d{2}$/.test(date)||new Date(date+'T12:00:00').toLocaleDateString('en-CA')!==date||!times.includes(time)||new Date(date+'T'+time)<=new Date()||!Number.isInteger(capacity)||capacity<1||capacity>30||!/^\d+(?:\.\d{1,2})?$/.test(priceText)||!Number.isFinite(price)||price<=0||price>10000){toast('Revise título, data futura, horário, vagas (1 a 30) e preço por aluno (até R$ 10.000).');return false}
 if(classAt('p1',date,time)||availability('p1',date).blocked.includes(time)||state.appointments.some(a=>a.pro==='p1'&&a.date===date&&a.time===time&&a.status!=='Cancelado')){toast('Horário ocupado ou bloqueado. Escolha outro.');return false}
 state.groupClasses.push({id:uid(),pro:'p1',title,date,time,capacity,price,status:'Ativa'});audit('Turma criada',title,date+' '+time);save();return true
}
function followupState(id){if(!Object.hasOwn(state.followupsDemo,id)||['__proto__','constructor','prototype'].includes(id))return null;const value=state.followupsDemo[id];return value&&value.owner==='p1'?value:null}
function followupLabel(value){if(!value)return 'Sem planejamento';if(value.done===true)return 'Contato registrado';return value.date<dateKey()?'Atrasado':value.date===dateKey()?'Hoje':'Planejado'}
function followupList(){if(state.role!=='profissional')return [];return state.students.filter(s=>(String(s.name)+' '+String(s.goal)).toLocaleLowerCase('pt-BR').includes(followQuery.toLocaleLowerCase('pt-BR'))&&(!followFilter||followupLabel(followupState(s.id))===followFilter))}
function followupRows(){return followupList().map(s=>{const plan=followupState(s.id);return `<tr><td><strong>${esc(s.name)}</strong><p>${esc(s.goal)}</p></td><td>${esc(plan?.date||'Não definido')}</td><td>${esc(followupLabel(plan))}</td><td>${esc(plan?.notes||'')}</td><td>${btn('Planejar contato','plan-followup','secondary small',`data-id="${esc(s.id)}"`)}${plan?btn(plan.done?'Reabrir planejamento':'Registrar contato','toggle-followup','secondary small',`data-id="${esc(s.id)}"`):''}</td></tr>`}).join('')||'<tr><td colspan="5">Nenhum aluno para estes filtros.</td></tr>'}
function followupPage(){if(state.role!=='profissional')return '<div class="empty">Acompanhamento disponível para o perfil profissional.</div>';return head('Acompanhamento dos alunos','Planeje seus próximos contatos na demonstração.')+`<div class="notice">Organização manual dos cadastros demonstrativos. Sem análise de aderência por IA, envio de mensagens ou alertas externos. Use informações fictícias.</div><section class="card"><div class="flex section"><label>Buscar aluno<input id="follow-query" maxlength="100" value="${esc(followQuery)}"></label><label>Planejamento<select id="follow-filter"><option value="">Todos</option>${['Sem planejamento','Atrasado','Hoje','Planejado','Contato registrado'].map(label=>`<option ${followFilter===label?'selected':''}>${label}</option>`).join('')}</select></label>${btn('Limpar filtros','clear-followup-filters','secondary')}</div><div class="tablewrap"><table><thead><tr><th scope="col">Aluno</th><th scope="col">Data planejada</th><th scope="col">Situação</th><th scope="col">Notas</th><th scope="col">Ações</th></tr></thead><tbody id="followup-rows">${followupRows()}</tbody></table></div></section>`}
function saveFollowup(id,form){if(['__proto__','constructor','prototype'].includes(id)||state.role!=='profissional'||!state.students.some(s=>s.id===id))return false;const date=form.get('date'),notes=form.get('notes');if(!WearableCore.validMetricDate(date)||typeof notes!=='string'||notes.length>500){toast('Revise a data e as notas (até 500 caracteres).');return false}state.followupsDemo[id]={owner:'p1',date,notes:notes.trim(),done:false};return true}
function readingList(){if(state.role!=='profissional')return [];return state.readingsDemo.filter(r=>r&&r.owner==='p1'&&RadarCore.safeReadingURL(r.url)&&(!readingArea||r.specialty===readingArea)&&(!readingStatus||(readingStatus==='read'?r.read===true:r.read!==true))&&(String(r.title)+' '+String(r.notes)).toLocaleLowerCase('pt-BR').includes(readingQuery.toLocaleLowerCase('pt-BR'))).slice(0,30)}
function addReadingDemo(form){if(state.role!=='profissional')return false;let record;try{record=RadarCore.readingDraft(Object.fromEntries(['title','specialty','url','notes'].map(k=>[k,form.get(k)])))}catch(error){toast(error.message);return false}if(state.readingsDemo.filter(r=>r.owner==='p1').length>=30){toast('Limite de 30 referências nesta demonstração.');return false}state.readingsDemo.unshift({...record,id:uid(),owner:'p1',read:false});return true}
function readingRows(){return readingList().map(r=>`<section class="card"><div class="sectionhead"><h3>${esc(r.title)}</h3><span class="pill">${r.read?'Leitura registrada':'Para ler'}</span></div><p class="muted">${esc(r.specialty)} · Referência inserida manualmente</p><p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(r.notes)}</p><a class="textbtn" href="${esc(RadarCore.safeReadingURL(r.url))}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">Abrir referência externa</a><div class="flex section">${btn(r.read?'Desmarcar leitura':'Registrar leitura','toggle-reading','secondary small',`data-id="${esc(r.id)}"`)}${btn('Excluir referência','delete-reading','secondary small',`data-id="${esc(r.id)}"`)}</div></section>`).join('')||'<div class="empty">Nenhuma referência para estes filtros.</div>'}
function readingPage(){if(state.role!=='profissional')return '<div class="empty">Radar disponível para o perfil profissional.</div>';return head('Radar 369','Organize sua lista de leitura por especialidade.')+`<div class="notice">Lista manual desta demonstração, sem busca automática ou validação científica. Registrar leitura não verifica a fonte. Use dados fictícios; links abrem páginas externas.</div><div class="grid cols2"><form id="reading-form" class="card"><h2>Adicionar referência</h2><label>Título<input name="title" maxlength="160" required></label><label>Especialidade<select name="specialty">${RadarCore.RADAR_AREAS.map(area=>`<option>${esc(area)}</option>`).join('')}</select></label><label>URL HTTPS<input name="url" type="url" maxlength="2000" required placeholder="https://..."></label><label>Notas de leitura<textarea name="notes" maxlength="2000"></textarea></label><button class="btn" type="submit">Guardar referência</button></form><section><div class="card"><h2>Lista de leitura</h2><label>Buscar<input id="reading-query" maxlength="100" value="${esc(readingQuery)}"></label><label>Especialidade<select id="reading-area"><option value="">Todas</option>${RadarCore.RADAR_AREAS.map(a=>`<option ${readingArea===a?'selected':''}>${esc(a)}</option>`).join('')}</select></label><label>Status<select id="reading-status"><option value="">Todos</option><option value="unread" ${readingStatus==='unread'?'selected':''}>Para ler</option><option value="read" ${readingStatus==='read'?'selected':''}>Leitura registrada</option></select></label>${btn('Limpar filtros','clear-reading-filters','secondary')}</div><div id="reading-rows" class="grid section">${readingRows()}</div></section></div>`}
function expertSupport(){
 if(state.role!=='profissional')return '<div class="empty">Apoio disponível para o perfil profissional.</div>';
 const expert=ExpertCore.findExpert(briefExpert)||ExpertCore.EXPERTS[0];
 return head('Apoio profissional','Organize um briefing para marketing, carreira ou conteúdo.')+`<div class="notice">Preparação manual, sem resposta de IA ou envio externo. Use dados fictícios e evite informações pessoais ou clínicas.</div><div class="grid cols2"><form id="expert-brief-form" class="card"><h2>Preparar briefing</h2><label>Perfil de apoio<select id="brief-expert" name="expert">${ExpertCore.EXPERTS.map(e=>`<option value="${e.id}" ${e.id===expert.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label><label>Objetivo<textarea name="objective" maxlength="500" required></textarea></label><label>Público<input name="audience" maxlength="200" required></label><label>Formato<select id="brief-format" name="format">${expert.formats.map(f=>`<option>${esc(f)}</option>`).join('')}</select></label><button class="btn" type="submit">Preparar briefing</button></form><section class="card"><h2>Briefing preparado</h2>${expertBrief?`<pre style="white-space:pre-wrap;overflow-wrap:anywhere;font:inherit">${esc(ExpertCore.expertBriefText(expertBrief))}</pre>${btn('Baixar briefing em texto','export-expert-brief','secondary')}`:'<p class="muted">Preencha o objetivo e o público para preparar seu documento.</p>'}<p class="muted section">O briefing fica disponível até você trocar de perfil ou recarregar a página. Baixe para guardar uma cópia.</p></section></div>`
}
function prepareDemoBrief(form){if(state.role!=='profissional')return false;try{const data=ExpertCore.prepareExpertBrief(Object.fromEntries(['expert','objective','audience','format'].map(k=>[k,form.get(k)])));expertBrief=data;briefExpert=data.expert;return true}catch(error){toast(error.message);return false}}
function downloadExpertBrief(){if(state.role!=='profissional'||!expertBrief)return;const url=URL.createObjectURL(new Blob([ExpertCore.expertBriefText(expertBrief)],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='369-wellness-briefing.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Briefing exportado sem envio externo.')}
function groupOverviewList(){
 if(!['aluno','profissional'].includes(state.role))return [];
 const professional=state.role==='profissional';
 const rows=professional?state.groupClasses.filter(g=>g.pro==='p1').map(g=>({group:g,booking:null,status:g.status})):state.appointments.filter(a=>a.studentId==='viewer'&&a.groupId).flatMap(a=>{const g=state.groupClasses.find(g=>g.id===a.groupId&&g.pro===a.pro);return g?[{group:g,booking:a,status:a.status}]:[]});
 return rows.filter(({group:g,status})=>{const t=new Date(g.date+'T'+g.time).getTime();return Number.isFinite(t)&&(!classStatus||status===classStatus)&&(classPeriod==='all'||(classPeriod==='upcoming'?t>=Date.now():t<Date.now()))&&(String(g.title)+' '+g.date+' '+g.time).toLocaleLowerCase('pt-BR').includes(classQuery.toLocaleLowerCase('pt-BR'))}).sort((a,b)=>(b.group.date+b.group.time).localeCompare(a.group.date+a.group.time));
}
function groupOverviewRows(){return groupOverviewList().map(({group:g,booking:a,status})=>`<tr><td>${esc(g.title)}</td><td>${esc(g.date)} · ${esc(g.time)}</td><td>${esc(status)}</td><td>${state.role==='profissional'?classBookings(g.id).length+' / '+esc(g.capacity):money(a.deposit)}</td><td>${state.role==='profissional'?btn('Ver dia na agenda','open-class-day','secondary small',`data-id="${esc(g.id)}"`):canCancelAppointment(a)?btn('Cancelar inscrição','cancel','secondary small',`data-id="${esc(a.id)}"`):''}</td></tr>`).join('')||'<tr><td colspan="5">Nenhum resultado para estes filtros.</td></tr>'}
function groupOverview(){
 if(!['aluno','profissional'].includes(state.role))return '<div class="empty">Visualização disponível para aluno e profissional.</div>';
 const prof=state.role==='profissional',statuses=prof?['Ativa','Cancelada']:['Confirmado','Concluído','Ausente','Cancelado'];
 return head('Aulas coletivas',prof?'Consulte suas turmas e acesse a agenda de cada dia.':'Acompanhe suas inscrições e encontre turmas disponíveis.')+`<div class="notice">Turmas e inscrições demonstrativas deste navegador. Reservas, pagamentos e presença reais dependem da integração com o servidor.</div><section class="card section"><h2>${prof?'Suas turmas':'Suas inscrições'}</h2><div class="flex section"><label>Buscar no histórico<input id="class-search" maxlength="100" value="${esc(classQuery)}" placeholder="Título, data ou horário"></label><label>Status<select id="class-status"><option value="">Todos</option>${statuses.map(x=>`<option ${classStatus===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Período<select id="class-period">${[['all','Todos'],['upcoming','A partir de agora'],['past','Anteriores a agora']].map(([value,label])=>`<option value="${value}" ${classPeriod===value?'selected':''}>${label}</option>`).join('')}</select></label>${btn('Limpar filtros','clear-class-filters','secondary')}</div><div class="tablewrap"><table><thead><tr><th scope="col">Turma</th><th scope="col">Quando</th><th scope="col">Status</th><th scope="col">${prof?'Ocupação':'Sinal simulado'}</th><th scope="col">Ação</th></tr></thead><tbody id="class-overview-rows">${groupOverviewRows()}</tbody></table></div></section>${prof?`<a class="btn lime" href="#agenda">Criar turma na agenda</a>`:groupSection()}`
}
function canCancelAppointment(ap){return state.role==='aluno'&&!!ap&&(ap.studentId==='viewer'||!ap.studentId)&&['Confirmado','Pendente'].includes(ap.status)}
function groupSection(){const prof=state.role==='profissional';let list=state.groupClasses.filter(g=>g.status!=='Cancelada'&&(prof?g.date===agendaDate:availability(g.pro,g.date).released&&!availability(g.pro,g.date).blocked.includes(g.time)&&new Date(g.date+'T'+g.time)>new Date())).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `<section class="card section"><div class="sectionhead"><div><h2>Aulas coletivas</h2><p>${prof?'Organize turmas e acompanhe as vagas.':'Escolha uma turma com vagas disponíveis.'}</p></div>${prof?btn('Criar turma','create-class','lime'):''}</div><div class="notice">Turmas e inscrições demonstrativas. Não há cobrança ou reserva real.</div>${list.length?list.map(g=>`<div class="row"><div><h3>${esc(g.title)}</h3><p>${dayName(g.date)} · ${g.time}–${String((Number(g.time.slice(0,2))+1)%24).padStart(2,'0')}:00 · Rafael Costa</p><span class="pill">${classBookings(g.id).length} / ${g.capacity} vagas ocupadas</span><p>${money(g.price)} por aluno</p>${prof?classBookings(g.id).map(a=>`<small>${esc(a.studentName||'Aluno da demonstração')} · ${esc(a.status)}</small>`).join('<br>'):''}</div>${prof?btn('Cancelar turma','cancel-class','secondary small',`data-id="${esc(g.id)}"`):btn(canEnroll(g)?'Inscrever-se':state.appointments.some(a=>a.groupId===g.id&&a.studentId==='viewer'&&a.status!=='Cancelado')?'Inscrição confirmada':'Sem vagas','enroll-class','secondary small',`data-id="${esc(g.id)}" ${canEnroll(g)?'':'disabled'}`)}</div>`).join(''):'<div class="empty">Nenhuma turma disponível neste momento.</div>'}</section>`}
function available(pro,date,time){let a=availability(pro,date);return a.released&&!a.blocked.includes(time)&&!classAt(pro,date,time)&&!state.appointments.some(x=>x.pro===pro&&x.date===date&&x.time===time&&x.status!=='Cancelado')&&new Date(date+'T'+time)>new Date()}
function agenda(){if(state.role==='profissional'){let a=availability('p1',agendaDate);return head('Sua agenda, do seu jeito','Configure horários, libere o dia e acompanhe os encontros.')+`<div class="notice">Agenda demonstrativa de Rafael Costa. As alterações aparecem também na área do aluno, neste navegador. Dias ficam ocultos até você clicar em Liberar dia. Grade das 05h às 00h.</div>${calendarMonth()}<div class="grid cols3 section">${stat('Pendentes de confirmação',appointments().filter(x=>x.status==='Pendente').length,'calendar')}${stat('Confirmados / na grade',appointments().filter(x=>x.status==='Confirmado').length,'calendar')}${stat('Concluídos',appointments().filter(x=>x.status==='Concluído').length,'check')}</div><div class="grid cols2"><section class="card"><div class="sectionhead"><h2>Disponibilidade</h2><input type="date" id="agenda-date" aria-label="Dia da agenda" min="${dateKey()}" value="${agendaDate}"></div><p class="muted">Clique em um horário para bloquear ou liberar. Sessões de 60 minutos.</p><div class="slots">${times.map(t=>{let group=classAt('p1',agendaDate,t),booked=state.appointments.find(x=>x.pro==='p1'&&x.date===agendaDate&&x.time===t&&x.status==='Confirmado');return `<button class="slot ${a.blocked.includes(t)?'blocked':''}" data-action="toggle-slot" data-time="${t}" ${booked||group?'disabled':''}>${t}${group?' · Turma: '+esc(group.title):booked?' · '+esc(booked.studentName||'Aluno da demonstração'):''}</button>`}).join('')}</div><form id="settings-form"><div class="grid cols2"><label>Sinal (%)<input name="deposit" type="number" min="0" max="100" required value="${a.deposit}"></label><label>Cancelar sem multa até (horas)<input name="cancelHours" type="number" min="0" max="168" required value="${a.cancelHours}"></label></div><button class="btn secondary">Salvar regras do dia</button></form><div class="row"><span class="pill">${a.released?'Dia liberado':'Dia oculto para alunos'}</span>${btn(a.released?'Ocultar dia':'Liberar dia','release-day','lime')}</div></section><section class="card"><h2>Atendimentos</h2>${appointmentRows()}</section></div>${groupSection()}`}return head('Minha agenda','Reserve tempo para cuidar de você.',`<a class="btn" href="#profissionais">Novo agendamento ${icon('arrow')}</a>`)+`<div class="grid cols3">${stat('Confirmados',appointments().filter(a=>a.status==='Confirmado').length,'calendar')}${stat('Concluídos',appointments().filter(a=>a.status==='Concluído').length,'check')}${stat('Cancelados',state.appointments.filter(a=>a.status==='Cancelado').length,'calendar')}</div><section class="card section"><h2>Seus encontros</h2>${appointmentRows()}</section>${groupSection()}`}
function nutrition(){return head('Nutrir uma boa rotina','Organize o acompanhamento da sua alimentação.')+`<div class="notice">Exemplo de organização de refeições, sem prescrição nutricional. Procure acompanhamento individualizado.</div><div class="grid cols2"><section class="card"><div class="sectionhead"><h2>Minha rotina alimentar</h2><span class="pill">Exemplo</span></div>${[['07:30','Café da manhã','Espaço para orientações do nutricionista'],['12:00','Almoço','Espaço para o plano alimentar individual'],['16:00','Lanche','Orientações conforme sua rotina'],['19:30','Jantar','Acompanhamento e ajustes profissionais']].map(([t,n,d])=>`<div class="row"><span class="pill">${t}</span><div class="spacer"><h3>${n}</h3><p>${d}</p></div>${icon('leaf')}</div>`).join('')}</section><section>${proCard(pros[1])}<div class="card section"><h3>Hidratação de hoje</h3><div class="balance">${waterCount()} <small style="font-size:16px">ml</small></div>${btn('Registrar 250 ml','water','secondary')}</div></section></div>`}
function community(){let posts=[...state.posts,{id:'welcome',name:'Equipe 369',text:'Evoluir também é celebrar os pequenos passos. Qual hábito você quer fortalecer nesta semana?',date:'Comunidade de demonstração'}];return head('Evoluir fica melhor junto','Compartilhe sua jornada e celebre cada conquista.')+`<div class="notice">Publicações locais: este mural não é compartilhado com outras pessoas.</div><div class="grid cols2"><section><form class="card" id="post-form"><label for="post-text">Como está a sua jornada hoje?</label><textarea id="post-text" name="text" maxlength="1200" required placeholder="Compartilhe uma pequena conquista..."></textarea><button class="btn">Publicar no mural local</button></form></section><section>${posts.map(p=>`<article class="card post" style="margin-bottom:16px"><div class="rowleft"><div class="avatar">${esc(p.name.slice(0,2).toUpperCase())}</div><div><h3>${esc(p.name)}</h3><small>${esc(p.date)}</small></div></div><p>${esc(p.text)}</p>${btn((state.likes.includes(p.id)?'♥':'♡')+' Apoiar','like','secondary small',`data-id="${p.id}"`)}</article>`).join('')}</section></div>`}
function chatThread(){return state.role==='profissional'?'p1':chatPro}
function threadMessages(){return state.messages.filter(m=>m.pro===chatThread())}
function draftExportText(){
 if(!['aluno','profissional'].includes(state.role)||!pros.some(p=>p.id===chatThread()))return null;
 const messages=threadMessages();if(!messages.length)return null;
 if(messages.length>250||messages.some(m=>typeof m.text!=='string'||m.text.length>2000))return null;
 const p=pros.find(p=>p.id===chatThread());
 return '369 WELLNESS — Rascunhos locais\nProfissional: '+p.name+'\nSem envio, assinatura ou sincronização.\n\n'+messages.map(m=>(m.authorRole==='profissional'?'Nota do profissional':'Rascunho do aluno')+' · '+String(m.time||'')+'\n'+m.text).join('\n\n');
}
function downloadDrafts(){const text=draftExportText();if(text===null){toast('Selecione uma conversa com até 250 rascunhos válidos.');return}const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='369-wellness-rascunhos-'+chatThread()+'.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Rascunhos desta conversa exportados.')}
function chat(){let p=pros.find(p=>p.id===chatThread())||pros[0],messages=threadMessages();return head('Mensagens','Organize suas conversas por profissional.')+`<div class="notice">Rascunhos locais de conversa, sem envio ou respostas automáticas. Não inclua dados sensíveis.</div><section class="card">${state.role==='aluno'?`<label>Escolher profissional<select id="chat-professional" aria-label="Profissional da conversa">${pros.map(x=>`<option value="${x.id}" ${p.id===x.id?'selected':''}>${x.name} · ${x.area}</option>`).join('')}</select></label>`:''}<div class="rowleft"><div class="avatar ${p.color}">${p.initials}</div><div><h3>${p.name}</h3><small>${p.area} · Perfil demonstrativo</small></div></div>${messages.length?btn('Exportar rascunhos em texto','export-chat','secondary'):''}<div class="chatarea">${messages.length?messages.map(m=>`<div class="message"><p>${esc(m.text)}</p><div><small>${m.authorRole==='profissional'?'Nota do profissional':'Rascunho do aluno'} · ${esc(m.time)}</small>${m.authorRole===state.role?btn('Apagar rascunho','delete-message','secondary small',`data-id="${esc(m.id)}"`):''}</div></div>`).join(''):'<div class="empty">Nenhum rascunho para este profissional. Anote suas dúvidas para a próxima conversa.</div>'}</div><form id="chat-form" class="flex"><input name="text" maxlength="2000" required aria-label="Mensagem" placeholder="Escreva um rascunho..." class="spacer"><button class="btn">Salvar rascunho</button></form></section>`}
const rankingData=[{name:'Mariana Silva',role:'Aluna',type:'aluno',points:1240},{name:'Rafael Costa',role:'Profissional',type:'profissional',points:1120},{name:'Camila Oliveira',role:'Profissional',type:'profissional',points:980},{name:'Pedro Martins',role:'Aluno',type:'aluno',points:850}];
function rankingList(){return rankingData.slice().sort((a,b)=>b.points-a.points||a.name.localeCompare(b.name,'pt-BR')).map((p,i)=>({...p,position:i+1})).filter(p=>(!rankType||p.type===rankType)&&p.name.toLocaleLowerCase('pt-BR').includes(rankQuery.toLocaleLowerCase('pt-BR')))}
function rankingRows(){return rankingList().map(p=>`<tr><td>#${p.position}</td><td>${esc(p.name)}</td><td>${esc(p.role)}</td><td>${p.points.toLocaleString('pt-BR')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nenhum participante encontrado.</td></tr>'}
function ranking(){let list=rankingData.slice().sort((a,b)=>b.points-a.points||a.name.localeCompare(b.name,'pt-BR'));return head('Uma comunidade em movimento','Explore o ranking geral e os participantes por perfil.')+`<div class="notice">Ranking ilustrativo, ordenado por pontos fixos de demonstração. Sem vínculo com cashback ou premiações reais. Os filtros preservam a posição no ranking geral.</div><h2 class="section">Destaques do ranking geral</h2><div class="grid cols3">${list.slice(0,3).map((p,i)=>`<section class="card" style="text-align:center;background:${i===0?'#eef7df':'white'}"><span class="ranknum">0${i+1}</span><div class="avatar" style="margin:14px auto">${esc(p.name.split(' ').map(x=>x[0]).join(''))}</div><h2>${esc(p.name)}</h2><p class="muted">${esc(p.role)}</p><div class="balance" style="font-size:30px">${p.points.toLocaleString('pt-BR')} <small style="font-size:12px">pontos</small></div></section>`).join('')}</div><section class="card section"><div class="flex" style="margin-bottom:20px"><input id="rank-search" class="spacer" placeholder="Buscar participante" aria-label="Buscar participante do ranking" value="${esc(rankQuery)}"><select id="rank-type" aria-label="Filtrar perfil no ranking"><option value="">Geral</option><option value="aluno" ${rankType==='aluno'?'selected':''}>Alunos</option><option value="profissional" ${rankType==='profissional'?'selected':''}>Profissionais</option></select></div><div class="tablewrap"><table><thead><tr><th>Posição geral</th><th>Participante</th><th>Perfil</th><th>Pontos demonstrativos</th></tr></thead><tbody id="rank-rows">${rankingRows()}</tbody></table></div></section>`}
function wallet(){let total=state.appointments.reduce((s,a)=>s+(a.status==='Cancelado'&&!a.retained?0:a.deposit),0);return head('Minha carteira','Acompanhe os valores simulados dos seus agendamentos.')+`<div class="notice">Nenhum dinheiro é movimentado. Pagamentos, depósitos, saques e cashback reais ainda não estão conectados.</div><div class="grid cols2"><section class="hero"><div><div class="eyebrow">SINAIS SIMULADOS</div><div class="balance">${money(total)}</div><p>Valores de teste, sem cobrança real.</p></div>${icon('wallet')}</section><section class="card"><h2>Transparência em cada etapa</h2><p class="muted" style="margin:15px 0">O sinal é calculado a partir do valor da sessão e da regra definida na agenda do profissional.</p><a class="btn secondary" href="#agenda">Consultar agendamentos</a></section></div><section class="card section"><h2>Histórico de simulações</h2>${state.appointments.length?state.appointments.map(a=>`<div class="row"><div><h3>${esc(a.groupTitle||pros.find(p=>p.id===a.pro).service)}</h3><p>${dayName(a.date)} · ${esc(a.status)}${a.status==='Cancelado'||a.status==='Ausente'?(a.retained?' · sinal retido na simulação':' · sinal devolvido na simulação'):''}</p></div><strong>${money(a.deposit)}</strong></div>`).join(''):'<div class="empty">Nenhuma transação simulada.</div>'}</section>`}
function studentRows(){return state.students.filter(s=>(!studentFilter||s.status===studentFilter)&&(s.name+' '+s.goal).toLocaleLowerCase('pt-BR').includes(studentQuery.toLocaleLowerCase('pt-BR'))).map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td>${esc(s.goal)}</td><td><span class="pill">${esc(s.status)}</span></td><td><div class="flex">${btn('Ver / editar','edit-student','secondary small',`data-id="${esc(s.id)}"`)}${btn(s.status==='Ativo'?'Pausar':'Reativar','student-status','secondary small',`data-id="${esc(s.id)}"`)}</div></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nenhum aluno encontrado.</td></tr>'}

function reportDates(){const count=[7,30,90].includes(reportDays)?reportDays:30;return Array.from({length:count},(_,i)=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-count+1+i);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')})}
function reportData(){
 if(!['aluno','profissional'].includes(state.role))return null;
 const dates=reportDates(),allowed=new Set(dates),professional=state.role==='profissional';
 const daily=professional?[]:dates.map(date=>({date,workouts:Object.entries(state.completed).filter(([k,v])=>v===true&&(k===date||k.startsWith(date+'::'))).length,water:Number.isFinite(state.water[date])&&state.water[date]>=0?state.water[date]:0}));
 const sessions=state.appointments.filter(a=>allowed.has(a.date)&&['Confirmado','Concluído','Ausente','Cancelado'].includes(a.status)&&(professional?a.pro==='p1':a.studentId==='viewer'||!a.studentId)).sort((a,b)=>(a.date+String(a.time)).localeCompare(b.date+String(b.time)));
 const completed=sessions.filter(a=>a.status==='Concluído').length,absent=sessions.filter(a=>a.status==='Ausente').length;
 return {dates,daily,sessions,completed,absent,attendance:completed+absent?Math.round(completed/(completed+absent)*100):null,workouts:daily.reduce((n,d)=>n+d.workouts,0),activeDays:daily.filter(d=>d.workouts>0).length,water:daily.reduce((n,d)=>n+d.water,0)};
}
function progressReport(){
 const data=reportData();if(!data)return '';const prof=state.role==='profissional';
 const controls=`<div class="flex"><label>Período<select id="report-period" aria-label="Período do relatório">${[7,30,90].map(n=>`<option value="${n}" ${reportDays===n?'selected':''}>Últimos ${n} dias</option>`).join('')}</select></label>${btn('Exportar CSV','export-report','secondary')}</div>`;
 return head(prof?'Relatórios de atendimentos':'Minha evolução',`${dayName(data.dates[0])} a ${dayName(data.dates.at(-1))} · inclui hoje`,controls)+`<div class="notice">${prof?'Atendimentos demonstrativos de Rafael Costa. Os registros de treino e água do aluno não são compartilhados neste relatório.':'Registros deste navegador. O volume de água é o que você registrou, sem meta ou recomendação de consumo.'} Dados sem registro são exibidos como zero; não representam avaliação clínica.</div><div class="grid cols3 section">${prof?stat('Atendimentos concluídos',data.completed,'calendar')+stat('Ausências registradas',data.absent,'users')+stat('Presença nos atendimentos avaliados',data.attendance===null?'Sem avaliação':data.attendance+'%','check'):stat('Treinos concluídos',data.workouts,'workout')+stat('Dias com treino concluído',data.activeDays,'calendar')+stat('Água registrada no período',(data.water/1000).toLocaleString('pt-BR')+' L','drop')}</div>${prof?'<p class="muted">Presença = concluídos ÷ (concluídos + ausências). Agendamentos confirmados e cancelados não entram nesse cálculo.</p>':`<section class="card section"><h2>Registro diário</h2><div class="tablewrap"><table><thead><tr><th>Data</th><th>Treinos concluídos</th><th>Água registrada (ml)</th></tr></thead><tbody>${[...data.daily].reverse().map(d=>`<tr><td>${dayName(d.date)}</td><td>${d.workouts}</td><td>${d.water.toLocaleString('pt-BR')}</td></tr>`).join('')}</tbody></table></div></section>`}<section class="card section"><h2>Atendimentos no período</h2><div class="tablewrap"><table><thead><tr><th>Data / horário</th><th>${prof?'Aluno':'Profissional'}</th><th>Tipo</th><th>Situação</th></tr></thead><tbody>${data.sessions.map(a=>`<tr><td>${dayName(a.date)} · ${esc(a.time)}</td><td>${esc(prof?(a.studentName||'Aluno sem identificação'):(pros.find(p=>p.id===a.pro)?.name||'Profissional sem identificação'))}</td><td>${esc(a.groupId?(a.groupTitle||'Aula coletiva'):'Individual')}</td><td>${esc(a.status)}</td></tr>`).join('')||'<tr><td colspan="4">Nenhum atendimento registrado no período.</td></tr>'}</tbody></table></div></section>`;
}
function csvCell(value){let text=String(value??'');if(/^[\s\uFEFF]*[=+@-]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'}
function reportCSV(){const data=reportData();if(!data)return null;const prof=state.role==='profissional';const rows=[['369 WELLNESS','Relatório demonstrativo',data.dates[0],data.dates.at(-1)]];
 if(!prof){rows.push(['Registro diário','Data','Treinos concluídos','Água registrada (ml)']);for(const d of data.daily)rows.push(['Registro diário',d.date,d.workouts,d.water]);}
 else rows.push(['Resumo','Atendimentos concluídos','Ausências','Presença (%)'],['Resumo',data.completed,data.absent,data.attendance===null?'Sem avaliação':data.attendance]);
 rows.push(['Atendimento','Data','Horário',prof?'Aluno':'Profissional','Tipo','Situação']);for(const a of data.sessions)rows.push(['Atendimento',a.date,a.time,prof?(a.studentName||'Aluno sem identificação'):(pros.find(p=>p.id===a.pro)?.name||'Profissional sem identificação'),a.groupId?(a.groupTitle||'Aula coletiva'):'Individual',a.status]);return '\uFEFF'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n');
}
function downloadReport(){const csv=reportCSV();if(csv===null)return;const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='369-wellness-relatorio-'+state.role+'-'+reportDays+'-dias.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Relatório exportado com dados deste navegador.')}

function students(){return head(state.role==='admin'?'Participantes':'Meus alunos','Acompanhe objetivos e mantenha os cadastros organizados.',btn('Adicionar aluno','add-student',''))+`<div class="notice">Cadastros demonstrativos salvos apenas neste navegador. Não insira informações sensíveis.</div><section class="card"><div class="flex" style="margin-bottom:20px"><input id="student-search" class="spacer" aria-label="Buscar aluno por nome ou objetivo" placeholder="Buscar nome ou objetivo" value="${esc(studentQuery)}"><select id="student-filter" aria-label="Filtrar situação"><option value="">Todos</option><option ${studentFilter==='Ativo'?'selected':''}>Ativo</option><option ${studentFilter==='Pausado'?'selected':''}>Pausado</option></select></div><div class="tablewrap"><table><thead><tr><th>Aluno</th><th>Objetivo</th><th>Situação</th><th>Ações</th></tr></thead><tbody id="student-rows">${studentRows()}</tbody></table></div></section>`}

function frontendValidationCard(){const v=packageAudit.frontendValidation;if(!v)return '';return `<section class="card section"><h2>Validação do frontend consolidado</h2><div class="grid cols3 section">${stat('Build React','Aprovado','check')}${stat('Verificação de tipos','Aprovada','check')}${stat('Testes locais',v.regressionTests.passed,'shield')}</div><p>Dependências instaladas e versão de cada pacote registrada. A prévia aberta continua sendo a demonstração estática.</p><div class="notice">Auditoria de dependências: ${v.dependencyAudit.status==='passed'&&v.dependencyAudit.counts.total===0?'Nenhum alerta conhecido nas dependências instaladas nesta verificação. A cadeia CSS com alertas foi removida.':v.dependencyAudit.counts.total+' alertas em dependências; revisão pendente.'} Este resultado não certifica a segurança do aplicativo ou do servidor.</div>${v.sessionSecurity?'<p><strong>Login React revisado:</strong> atalhos com credenciais removidos e respostas antigas de renovação de sessão descartadas. Foram executados 10 testes locais específicos. O login real permanece sem validação no servidor.</p>':''}${v.notificationSecurity?'<p><strong>Notificações no código recebido:</strong> serviço de aviso de treino/dieta confere profissional, recurso e vínculo do aluno. Migração 0059 preparada para restringir criação direta e bloquear edição por cliente. Nove testes locais específicos passaram; nenhuma regra foi aplicada a um banco.</p>':''}${v.notificationInbox?'<p><strong>Caixa de avisos:</strong> consulta da própria conta e serviço para marcar como lido preparados no React. Paginação ajustada para retornar a uma página existente após a leitura; 14 testes locais específicos passaram. A prévia permite testar um aviso local ao salvar uma ficha. Nenhum serviço de banco foi ativado.</p>':''}${v.studentAssignment?'<p><strong>Criação de treino e dieta revisada:</strong> seletor paginado dos alunos vinculados, sem dados de contato ou saúde; vínculo conferido antes de salvar. Oito verificações locais específicas passaram. As permissões reais do servidor seguem pendentes.</p>':''}<p class="muted">Ainda faltam testes das telas React em navegador e validação de login, banco, permissões, pagamentos, IA e wearable no servidor.</p><small>Verificação em ${new Date(v.checkedAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})} · horário de Brasília</small></section>`}
function packageStatusPage(){if(state.role!=='admin')return '';return head('Status dos pacotes 0–15','Conferência de '+new Date(packageAudit.auditedAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})+' · horário de Brasília')+`<div class="notice">${esc(packageAudit.criterion)} Esta conferência é um retrato da versão publicada.</div><div class="grid cols3 section">${stat('Pacotes consolidados',packageAudit.consolidated,'settings')}${stat('Totalmente aplicados',packageAudit.fullyApplied,'check')}${stat('Módulos importados ausentes',packageAudit.uniqueMissingModules,'shield')}</div><section class="card"><h2>Aplicação por pacote</h2><p class="muted">A prévia usa fluxos reconstruídos. Não executa os componentes React ou hooks do código original.</p><div class="tablewrap"><table><thead><tr><th>Pacote</th><th>Escopo recebido</th><th>Aplicação na prévia</th><th>Status</th><th>Pendente para conclusão</th></tr></thead><tbody>${packageAudit.packages.map(p=>`<tr><td><strong>${String(p.number).padStart(2,'0')}</strong></td><td>${esc(p.scope)}</td><td>${esc(p.preview)}</td><td><span class="pill">${esc(p.status)}</span></td><td>${esc(p.pending)}</td></tr>`).join('')}</tbody></table></div></section>${frontendValidationCard()}<section class="card section"><h2>Próximas ações priorizadas</h2><ol><li><strong>P0:</strong> validar a experiência React em navegador após a atualização CSS. A conferência estática aponta ${packageAudit.unresolvedReferences} referências locais sem resolução.</li><li><strong>P0:</strong> validar autenticação, permissões e migrations em banco de teste antes de conectar os fluxos.</li><li><strong>P1:</strong> integrar pagamentos, ranking, IA e wearable, verificando cada fluxo antes de marcar seu pacote como concluído.</li></ol><p class="muted">Pacote 00: base sem numeração explícita, identificada na consolidação. Pacote 05: repetição de arquivos anteriores. As configurações de inicialização e os componentes compartilhados adicionados são reconstruções. O build e a verificação de tipos foram aprovados localmente; as integrações de servidor seguem pendentes.</p></section>`}

function auditRows(){if(state.role!=='admin')return '';const rows=state.audit.filter(x=>AuditCore.localAuditMatches(x,auditQuery,auditActor,auditAction));return rows.length?rows.map(x=>`<div class="row"><div><h3>${esc(x.action)}</h3><p>${esc(x.target)} · ${esc(AuditCore.auditDetailText(x.details))}</p><small>${esc(x.time)} · ${esc(x.actor)}</small></div></div>`).join(''):'<div class="empty">Nenhuma ação encontrada com estes filtros.</div>'}
function auditPage(){if(state.role!=='admin')return '';return head('Histórico de ações','Revise as alterações realizadas nesta demonstração.')+`<div class="notice">Histórico local, limitado a 200 ações. Não é um registro oficial de auditoria e pode ser apagado neste navegador. Campos com nomes de segredo conhecidos são ocultados na exibição.</div><section class="card"><div class="toolbar"><input id="audit-search" maxlength="100" aria-label="Buscar no histórico" placeholder="Buscar ação, destino ou detalhe" value="${esc(auditQuery)}"><select id="audit-actor" aria-label="Filtrar perfil responsável"><option value="">Todos os perfis</option>${['aluno','profissional','admin'].map(role=>`<option value="${role}" ${auditActor===role?'selected':''}>${{aluno:'Aluno',profissional:'Profissional',admin:'Administrador'}[role]}</option>`).join('')}</select><select id="audit-action" aria-label="Filtrar ação"><option value="">Todas as ações</option>${[...new Set(state.audit.map(x=>x.action))].sort().map(action=>`<option value="${esc(action)}" ${auditAction===action?'selected':''}>${esc(action)}</option>`).join('')}</select>${btn('Limpar filtros','clear-audit-filters','secondary small')}</div><div id="audit-rows">${auditRows()}</div></section>`}
function approvals(){return head('Aprovações profissionais','Explore o fluxo de análise de novos profissionais.')+`<div class="notice">Solicitações fictícias. Não há documentos ou credenciais reais para validar nesta versão.</div><section class="card">${state.approvals.map(a=>`<div class="row"><div><h3>${esc(a.name)}</h3><p>${esc(a.area)}</p><span class="pill">${esc(a.status)}</span>${a.reason?`<p>Motivo: ${esc(a.reason)}</p>`:''}</div><div class="flex">${a.status==='Pendente'?btn('Aprovar','approve','lime small',`data-id="${a.id}"`)+btn('Reprovar','reject','secondary small',`data-id="${a.id}"`):'Análise demonstrativa registrada'}</div></div>`).join('')}</section>`}
function dashboard(){let admin=state.role==='admin';return head(admin?'Visão da plataforma':'Bom trabalho começa com cuidado',admin?'Acompanhe os indicadores desta demonstração.':'Seu dia, seus alunos e seus próximos atendimentos.')+(admin?'':brandStory('profissional'))+`<div class="notice">Os indicadores refletem somente os dados de exemplo e as ações realizadas neste navegador.</div><div class="grid cols3">${stat('Alunos ativos',state.students.filter(s=>s.status==='Ativo').length,'users')}${stat('Atendimentos confirmados',appointments().filter(a=>a.status==='Confirmado').length,'calendar')}${stat(admin?'Aprovações pendentes':'Atendimentos concluídos',admin?state.approvals.filter(a=>a.status==='Pendente').length:appointments().filter(a=>a.status==='Concluído').length,'shield')}</div><div class="grid cols2 section"><section class="card"><div class="sectionhead"><h2>${admin?'Solicitações profissionais':'Próximos atendimentos'}</h2><a class="textbtn" href="#${admin?'aprovacoes':'agenda'}">Ver todos →</a></div>${admin?state.approvals.map(a=>`<div class="row"><div><h3>${a.name}</h3><p>${a.area}</p></div><span class="pill">${a.status}</span></div>`).join(''):appointmentRows()}</section><section class="hero"><div><div class="eyebrow">CUIDADO QUE APROXIMA</div><h2>${admin?'Uma rede para evoluir.':'Mais presença.<br>Mais evolução.'}</h2><p>${admin?'Explore os perfis, os agendamentos e a gestão dos participantes.':'Organize sua disponibilidade e acompanhe quem confia no seu trabalho.'}</p><a class="btn lime" href="#${admin?'alunos':'agenda'}">${admin?'Ver participantes':'Organizar agenda'} ${icon('arrow')}</a></div></section></div>`}
function demoChallenges(){return state.challengesDemo.filter(c=>c&&c.professional==='p1'&&typeof c.id==='string'&&ChallengeCore.challengeDuration(c.duration))}
function demoParticipation(id){return state.challengeParticipation.find(p=>p.challenge===id&&p.student==='s-demo')}
function createDemoChallenge(form){if(state.role!=='profissional')return false;let record;try{record=ChallengeCore.parseDemoChallenge(form.get('title'),form.get('description'),form.get('duration'))}catch(error){toast(error.message);return false}if(demoChallenges().length>=30){toast('Limite de 30 desafios demonstrativos.');return false}state.challengesDemo.push({...record,id:uid(),professional:'p1',closed:false});audit('Desafio demonstrativo criado',record.title,record.duration+' dias');return true}
function challengesPage(){
 if(!['aluno','profissional'].includes(state.role))return '<div class="empty">Desafios disponíveis para aluno e profissional.</div>';
 const professional=state.role==='profissional',list=demoChallenges();
 return head('Desafios','Acompanhe a participação diária na demonstração.')+`<div class="notice">Desafios locais e ilustrativos. Não geram pontos, medalhas ou benefícios reais. Use objetivos e dados fictícios.</div>${professional?`<form id="challenge-form" class="card section"><h2>Criar desafio demonstrativo</h2><label>Título<input name="title" maxlength="160" required></label><label>Descrição<textarea name="description" maxlength="2000"></textarea></label><label>Duração em dias<input name="duration" type="number" min="1" max="365" step="1" value="7" required></label><button class="btn" type="submit">Criar desafio</button></form>`:''}<div class="grid cols2">${list.length?list.map(c=>{const p=demoParticipation(c.id),days=ChallengeCore.challengeDays(p?.days,c.duration,dateKey()),done=days.length>=c.duration;return `<section class="card"><div class="sectionhead"><h2>${esc(c.title)}</h2><span class="pill">${c.closed?'Encerrado':'Aberto'}</span></div><p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(c.description)}</p><p class="muted">Rafael Costa · ${c.duration} dias</p>${p?`<p>${days.length} de ${c.duration} dias registrados${done?' · Meta demonstrativa concluída':''}</p><progress value="${days.length}" max="${c.duration}" aria-label="Dias registrados em ${esc(c.title)}"></progress>`:'<p class="muted">Nenhuma participação demonstrativa registrada.</p>'}<div class="flex section">${professional?(c.closed?'':btn('Encerrar desafio','close-challenge','secondary',`data-id="${esc(c.id)}"`)):p?(c.closed||(done&&!days.includes(dateKey()))?'':btn(days.includes(dateKey())?'Desmarcar hoje':'Registrar hoje','toggle-challenge-day','secondary',`data-id="${esc(c.id)}"`)):(c.closed?'':btn('Participar na demonstração','join-challenge','secondary',`data-id="${esc(c.id)}"`))}</div></section>`}).join(''):'<div class="empty">Nenhum desafio criado. Explore o perfil profissional para criar um exemplo.</div>'}</div>`
}
function wearableRows(){if(!['aluno','profissional'].includes(state.role))return [];return (state.wearableDemo||[]).filter(r=>r&&r.role===state.role).map(r=>WearableCore.metricProjection(r)).filter(r=>r.date!==null).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,30)}
function saveWearableDemo(form){
 if(!['aluno','profissional'].includes(state.role))return false;
 let record;try{record=WearableCore.parseDemoMetric(Object.fromEntries(['date','steps','heart_rate_avg','distance_meters','workouts_count'].map(k=>[k,form.get(k)])),dateKey())}catch(error){toast(error.message);return false}
 const own=state.wearableDemo.filter(r=>r.role===state.role&&r.date!==record.date);own.push({...record,role:state.role});own.sort((a,b)=>b.date.localeCompare(a.date));state.wearableDemo=[...state.wearableDemo.filter(r=>r.role!==state.role),...own.slice(0,30)];audit('Registro diário demonstrativo',record.date,'Salvo pelo próprio perfil, sem sincronização.');return true;
}
function wearablePage(){
 if(!['aluno','profissional'].includes(state.role))return '<div class="empty">Visualização disponível para aluno e profissional.</div>';
 const rows=wearableRows(),n=v=>v===null?'Não informado':new Intl.NumberFormat('pt-BR').format(v);
 return head('Smartwatch','Explore a visualização de registros diários.')+`<div class="notice">Conexão com relógios indisponível. Use dados fictícios: estes registros são manuais, demonstrativos e guardados neste navegador.</div><div class="grid cols2"><form id="wearable-form" class="card"><h2>Criar registro demonstrativo</h2><p class="muted">Um registro por dia e perfil. Salvar na mesma data substitui o registro anterior.</p><label>Data<input name="date" type="date" max="${dateKey()}" value="${dateKey()}" required></label>${[['steps','Passos','1'],['heart_rate_avg','FC média (bpm)','0.01'],['distance_meters','Distância (m)','0.01'],['workouts_count','Treinos realizados','1']].map(([key,label,step])=>`<label>${label}<input name="${key}" type="number" min="0" max="10000000" step="${step}" placeholder="Opcional"></label>`).join('')}<button class="btn" type="submit">Salvar registro demonstrativo</button></form><section class="card"><h2>Registros deste perfil</h2><p class="muted">Até 30 registros diários, sem interpretação clínica ou prescrição automática.</p><div class="tablewrap"><table><thead><tr><th scope="col">Data</th><th scope="col">Passos</th><th scope="col">FC média</th><th scope="col">Distância (m)</th><th scope="col">Treinos</th><th scope="col">Ação</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td>${esc(r.date)}</td><td>${n(r.steps)}</td><td>${n(r.heart_rate_avg)}</td><td>${n(r.distance_meters)}</td><td>${n(r.workouts_count)}</td><td>${btn('Excluir registro','delete-wearable','secondary small',`data-date="${esc(r.date)}"`)}</td></tr>`).join(''):'<tr><td colspan="6">Nenhum registro demonstrativo neste perfil.</td></tr>'}</tbody></table></div></section></div>`
}
function planComparison(){
 if(!['aluno','profissional'].includes(state.role))return '<div class="empty">Comparação disponível para aluno e profissional.</div>';
 const plans=PlanCatalog.plansForRole(state.role),chosen=PlanCatalog.planReference(state.role,comparisonPlan,planPeriod);
 return head('Comparar planos','Consulte os valores de referência por perfil e período.')+`<div class="notice">Valores do código recebido, sujeitos à confirmação. A comparação não ativa assinatura, benefícios ou cobrança.</div><div class="flex section" role="group" aria-label="Período de referência">${['monthly','annual'].map(period=>btn(period==='annual'?'Anual':'Mensal','compare-period',planPeriod===period?'lime':'secondary',`data-period="${period}" aria-pressed="${planPeriod===period}"`)).join('')}</div><div class="grid cols3">${plans.map(p=>{const ref=PlanCatalog.planReference(state.role,p.id,planPeriod);return `<section class="card"><h2>${esc(p.name)}</h2><p class="balance">${money(ref.amount)} <small style="font-size:16px">/ ${planPeriod==='annual'?'ano':'mês'}</small></p>${ref.serviceFee!==null?`<p class="muted">Tarifa de referência: ${money(ref.serviceFee)} por serviço.</p>`:''}${btn('Comparar '+esc(p.name),'compare-plan','secondary',`data-plan="${esc(p.id)}" aria-pressed="${comparisonPlan===p.id}"`)}</section>`}).join('')}</div><section class="card section" role="status" aria-live="polite">${chosen?`Selecionado para comparação: <strong>${esc(chosen.name)}</strong> · ${money(chosen.amount)} / ${planPeriod==='annual'?'ano':'mês'}.`:'Escolha um plano para comparar.'}<p class="muted">Nenhuma assinatura foi alterada. A prévia não define um plano real para sua conta.</p></section>`
}
function profile(){return head('Meu perfil','Pequenos ajustes para uma experiência com a sua cara.')+(state.role==='admin'?'':brandStory(state.role))+`<div class="grid cols2"><form class="card" id="profile-form"><h2>Sobre você</h2><label>Como quer ser chamado?<input name="name" required maxlength="60" value="${esc(state.profile.name)}"></label><label>Seu objetivo<input name="goal" required maxlength="160" value="${esc(state.profile.goal)}"></label><button class="btn">Salvar perfil</button></form><section class="card"><h2>Seus dados nesta versão</h2><p class="muted" style="margin:15px 0">As alterações são guardadas no armazenamento deste navegador. Não há autenticação de usuários, sincronização ou prontuário clínico nesta demonstração.</p><div class="flex">${btn('Exportar meus dados','export','secondary')}${btn('Apagar dados locais','reset','secondary')}</div><p class="statusline">Código original preservado · interface reconstruída a partir do pacote parcial.</p></section></div>`}
function render(){if((['aprovacoes','auditoria','pacotes'].includes(route)&&state.role!=='admin')||(['apoio','radar','acompanhamento'].includes(route)&&state.role!=='profissional')||(route==='alunos'&&!['admin','profissional'].includes(state.role))||(route==='evolucao'&&!['aluno','profissional'].includes(state.role))||(route==='conteudos'&&state.role!=='profissional')||(['chat','planos','smartwatch','desafios','aulas'].includes(route)&&state.role==='admin'))route='inicio';shell();const pages={inicio:home,evolucao:progressReport,conteudos:contentManager,profissionais:professionals,treino:workout,agenda,nutricao:nutrition,comunidade:community,chat,ranking,carteira:wallet,alunos:students,aprovacoes:approvals,auditoria:auditPage,pacotes:packageStatusPage,planos:planComparison,smartwatch:wearablePage,desafios:challengesPage,aulas:groupOverview,apoio:expertSupport,radar:readingPage,acompanhamento:followupPage,perfil:profile};$('#main').innerHTML=(pages[route]||home)();bind();if(route==='treino')paintTimer()}
function modal(content){$('#dialog').innerHTML=`<button class="close" aria-label="Fechar" data-action="close">×</button>${content}`;if(!$('#dialog').open)$('#dialog').showModal()}
function proModal(id){const p=pros.find(p=>p.id===id);modal(`<div class="avatar ${p.color}" style="width:64px;height:64px;margin-bottom:15px">${p.initials}</div><span class="pill ${p.color==='purple'?'purple':''}">${p.area}</span><h2 style="margin-top:12px">${p.name}</h2><h3>${p.specialty}</h3><p class="intro">${p.bio}</p><div class="notice">Perfil fictício · Credenciais profissionais não verificadas nesta demonstração.</div><div class="row"><span>${p.service}</span><strong>${money(p.price)}</strong></div><div style="margin-top:20px">${btn('Ver horários','book','full',`data-id="${p.id}"`)}${btn('Preparar conversa','open-conversation','secondary full',`data-id="${p.id}"`)}</div>`)}
function booking(id,date=agendaDate){bookingPro=id;agendaDate=date;slotSelection='';bookingModal()}
function bookingModal(){let p=pros.find(p=>p.id===bookingPro),a=availability(p.id,agendaDate);modal(`<span class="eyebrow">AGENDAMENTO DEMONSTRATIVO</span><h2 style="margin-top:10px">${p.service}</h2><p class="intro">${p.name} · ${money(p.price)} por sessão</p><label class="flex">Escolha o dia <input type="date" id="booking-date" aria-label="Dia do atendimento" min="${dateKey()}" value="${agendaDate}"></label>${a.released?`<div class="slots">${times.filter(t=>available(p.id,agendaDate,t)).map(t=>`<button class="slot ${slotSelection===t?'selected':''}" data-action="select-slot" data-time="${t}">${t}</button>`).join('')||'<p class="muted wide">Nenhum horário disponível neste dia.</p>'}</div>`:'<p class="intro">O profissional ainda não liberou este dia.</p>'}<div class="row"><span>Sinal de ${a.deposit}%</span><strong>${money(p.price*a.deposit/100)}</strong></div><p class="intro">Cancelamento sem retenção do sinal até ${a.cancelHours} horas antes. Depois desse prazo, o sinal é retido nesta simulação.</p><div class="notice">Ao confirmar, você simula o pagamento do sinal. Não há cobrança nem reserva real.</div>${btn('Simular sinal e confirmar','confirm-booking','full',slotSelection?'':'disabled')}`);$('#booking-date').onchange=e=>{if(e.target.value&&e.target.validity.valid)booking(bookingPro,e.target.value)}}
let seconds=60,timer=null;
